// Le nom du client est joint ici plutot que ramene par une seconde requete :
// c'est une valeur scalaire par ligne, la jointure ne multiplie rien. L'equipe,
// elle, est une collection : elle passe par ListMembersOfProjects, qui charge
// d'un coup les membres de toute la page.
//
// Les compteurs de taches sont lus tels quels : ce sont des colonnes tenues par
// declencheur, aucun COUNT n'est fait au rendu.
func (q *Queries) ListProjects(ctx context.Context, arg ListProjectsParams) ([]ListProjectsRow, error) {
	rows, err := q.db.Query(ctx, listProjects,
		arg.ViewerID,
		arg.Status,
		arg.ClientID,
		arg.Search,
		arg.Sort,
		arg.Dir,
		arg.PageOffset,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListProjectsRow{}
	for rows.Next() {
		var i ListProjectsRow
		if err := rows.Scan(
			&i.ID,
			&i.ClientID,
			&i.Name,
			&i.Status,
			&i.Progress,
			&i.HoursSold,
			&i.HoursSpent,
			&i.StartsOn,
			&i.DueOn,
			&i.TasksTotal,
			&i.TasksDone,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
			&i.Description,
			&i.Priority,
			&i.FigmaUrl,
			&i.ProdUrl,
			&i.PreprodUrl,
			&i.DeliverablesPending,
			&i.ClientName,
			&i.IsFavorite,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listServicesOfProjects = `-- name: ListServicesOfProjects :many
SELECT
    ps.project_id,
    s.id,
    s.name,
    s.color
FROM project_services ps
JOIN services s ON s.id = ps.service_id AND s.deleted_at IS NULL
WHERE ps.project_id = ANY($1::uuid[])
ORDER BY ps.project_id, s.name, s.id
`

type ListServicesOfProjectsRow struct {
	ProjectID uuid.UUID `json:"project_id"`
	ID        uuid.UUID `json:"id"`
	Name      string    `json:"name"`
	Color     string    `json:"color"`
}

// Services de plusieurs projets en une requete.
//
// Meme parade au N+1 que pour les equipes : une collection ne se joint pas a la
// liste — elle multiplierait les lignes — elle se charge d'un coup pour la page
// entiere, et le service la repartit ensuite.
func (q *Queries) ListServicesOfProjects(ctx context.Context, projectIds []uuid.UUID) ([]ListServicesOfProjectsRow, error) {
	rows, err := q.db.Query(ctx, listServicesOfProjects, projectIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListServicesOfProjectsRow{}
	for rows.Next() {
		var i ListServicesOfProjectsRow
		if err := rows.Scan(
			&i.ProjectID,
			&i.ID,
			&i.Name,
			&i.Color,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listTaskFiles = `-- name: ListTaskFiles :many
SELECT id, project_id, filename, content_type, size_bytes, storage_key, uploaded_by, created_at, task_id FROM attachments
WHERE task_id = ANY($1::uuid[])
ORDER BY task_id, created_at DESC
`

// Pieces jointes de plusieurs taches, pour le tiroir et le tableau.
func (q *Queries) ListTaskFiles(ctx context.Context, taskIds []uuid.UUID) ([]Attachment, error) {
	rows, err := q.db.Query(ctx, listTaskFiles, taskIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Attachment{}
	for rows.Next() {
		var i Attachment
		if err := rows.Scan(
			&i.ID,
			&i.ProjectID,
			&i.Filename,
			&i.ContentType,
			&i.SizeBytes,
			&i.StorageKey,
			&i.UploadedBy,
			&i.CreatedAt,
			&i.TaskID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

