const softDeleteProject = `-- name: SoftDeleteProject :exec
UPDATE projects SET deleted_at = now(), updated_at = now()
WHERE id = $1 AND deleted_at IS NULL
`

func (q *Queries) SoftDeleteProject(ctx context.Context, id uuid.UUID) error {
	_, err := q.db.Exec(ctx, softDeleteProject, id)
	return err
}

const updateProject = `-- name: UpdateProject :one
UPDATE projects SET
    name        = COALESCE($1::text, name),
    -- La description se vide en envoyant la chaine vide, pas en omettant le
    -- champ : COALESCE ne distingue pas « absent » de « efface », et un projet
    -- doit pouvoir perdre son resume.
    description = COALESCE($2::text, description),
    status      = COALESCE($3::text, status),
    priority    = COALESCE($4::text, priority),
    figma_url   = COALESCE($5::text, figma_url),
    prod_url    = COALESCE($6::text, prod_url),
    preprod_url = COALESCE($7::text, preprod_url),
    progress    = COALESCE($8::smallint, progress),
    hours_sold  = COALESCE($9::numeric, hours_sold),
    client_id   = COALESCE($10::uuid, client_id),
    starts_on   = CASE WHEN $11::boolean THEN NULL
                       ELSE COALESCE($12::date, starts_on) END,
    due_on      = CASE WHEN $13::boolean THEN NULL
                       ELSE COALESCE($14::date, due_on) END,
    updated_at  = now()
WHERE id = $15 AND deleted_at IS NULL
RETURNING id, client_id, name, status, progress, hours_sold, hours_spent, starts_on, due_on, tasks_total, tasks_done, created_by, created_at, updated_at, deleted_at, description, priority, figma_url, prod_url, preprod_url, deliverables_pending
`

type UpdateProjectParams struct {
	Name          *string    `json:"name"`
	Description   *string    `json:"description"`
	Status        *string    `json:"status"`
	Priority      *string    `json:"priority"`
	FigmaUrl      *string    `json:"figma_url"`
	ProdUrl       *string    `json:"prod_url"`
	PreprodUrl    *string    `json:"preprod_url"`
	Progress      *int16     `json:"progress"`
	HoursSold     *float64   `json:"hours_sold"`
	ClientID      *uuid.UUID `json:"client_id"`
	ClearStartsOn bool       `json:"clear_starts_on"`
	StartsOn      *time.Time `json:"starts_on"`
	ClearDueOn    bool       `json:"clear_due_on"`
	DueOn         *time.Time `json:"due_on"`
	ID            uuid.UUID  `json:"id"`
}

// Mise a jour partielle : chaque champ absent de la requete garde sa valeur.
// COALESCE sur un parametre nullable dit exactement cela, et evite d'ecrire
// une requete par champ modifiable.
func (q *Queries) UpdateProject(ctx context.Context, arg UpdateProjectParams) (Project, error) {
	row := q.db.QueryRow(ctx, updateProject,
		arg.Name,
		arg.Description,
		arg.Status,
		arg.Priority,
		arg.FigmaUrl,
		arg.ProdUrl,
		arg.PreprodUrl,
		arg.Progress,
		arg.HoursSold,
		arg.ClientID,
		arg.ClearStartsOn,
		arg.StartsOn,
		arg.ClearDueOn,
		arg.DueOn,
		arg.ID,
	)
	var i Project
	err := row.Scan(
		&i.ID,
		&i.ClientID,
		&i.Name,
		&i.Status,
		&i.Progress,
		&i.HoursSold,
		&i.HoursSpent,
		&i.StartsOn,
		&i.DueOn,
		&i.TasksTotal,
		&i.TasksDone,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.Description,
		&i.Priority,
		&i.FigmaUrl,
		&i.ProdUrl,
		&i.PreprodUrl,
		&i.DeliverablesPending,
	)
	return i, err
}
